type NotificationPreference = {
  enabled: boolean
}

const store = new Map<string, NotificationPreference>()

const USER_ID = 'me'

export async function getNotificationPreference(): Promise<boolean> {
  return store.get(USER_ID)?.enabled ?? false
}

export async function setNotificationPreference(enabled: boolean): Promise<void> {
  store.set(USER_ID, { enabled })
}

'use server'

import { refresh } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from '@/app/lib/data'

export async function toggleNotifications() {
  const enabled = await getNotificationPreference()
  await setNotificationPreference(!enabled)
  refresh()
}

import { toggleNotifications } from '@/app/actions'
import { getNotificationPreference } from '@/app/lib/data'

export default async function Home() {
  const enabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently <strong>{enabled ? 'On' : 'Off'}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">Turn notifications {enabled ? 'Off' : 'On'}</button>
      </form>
    </main>
  )
}

